css:
.headblock{
    margin: 0px 200px;

}
.divblock {
    margin: 10px 400px;
}
.option {
    height:60px;
    width: 200px;
    color:black;
    background-color: #e6f2ff;

}
.submit {
    color: blue;
    background-color: #e6f2ff;
    float: right;
    margin:50px;
    padding:5px 100px;
    border-radius: 10px;
}

javascript:
function check_submit(){

    frappe.msgprint("hello!!!!!!!!");
    const ans = [];
    const selects = document.querySelectorAll('select.option');

    selects.forEach(sel => {
        const rowname= sel.name;
        const explanationInput = document.querySelector(
            `.explanation[row-name="${rowname}"]`
        );

        ans.push({
            rowname: rowname,
            value: sel.value || "",
            explanation: explanationInput ? explanationInput.value.trim() : ""
        });

    });
    let lesson=document.getElementById('lesson').textContent;
    console.log(lesson);
    frappe.call({
        method: "studywave.student_learning.doctype.lesson.lesson.check_option",
        args:{
            ans:ans,
            lesson:lesson,
        }

    });
}
